package br.com.catalogo;

import java.net.*;
import java.net.http.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.*;
import java.sql.*;
import java.time.Duration;
import java.util.*;
import java.util.function.Consumer;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;

/** Explicit, resumable metadata synchronization. Never opens or moves remote file paths. */
final class CloudSync {
 record ConnectionInfo(String api,String deviceId,String catalogId,String email,String token,String databaseId){}
 record Pairing(String id,String code,URI url,String verifier,String deviceId){}
 record Result(int uploaded,int downloaded,int conflicts){}
 record Local(String id,boolean active,ObjectNode book,String cover){}
 record Link(String localId,String cloudId,long version,String hash,String base,boolean deleted,boolean restore){}
 final Biblioteca lib;final HttpClient http;final String databaseId;final Path config;
 static final Set<String> PRIVATE=Set.of("page","reader_position","pdf_scroll","epub_location","ocr_text","access_token","clerk_secret_key","password","api_key");
 CloudSync(Biblioteca lib)throws Exception{this(lib,HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(8)).build());}
 CloudSync(Biblioteca lib,HttpClient http)throws Exception{
  this.lib=lib;this.http=http;
  try(var c=lib.connect();var s=c.createStatement()){
   s.execute("CREATE TABLE IF NOT EXISTS cloud_profile(singleton INTEGER PRIMARY KEY CHECK(singleton=1),database_id TEXT NOT NULL)");
   try(var q=c.prepareStatement("INSERT OR IGNORE INTO cloud_profile VALUES(1,?)")){q.setString(1,UUID.randomUUID().toString());q.executeUpdate();}
   try(var r=s.executeQuery("SELECT database_id FROM cloud_profile WHERE singleton=1")){r.next();databaseId=r.getString(1);}
   s.execute("CREATE TABLE IF NOT EXISTS cloud_structure(scope TEXT PRIMARY KEY,snapshot TEXT NOT NULL)");
   s.execute("CREATE TABLE IF NOT EXISTS cloud_state(scope TEXT PRIMARY KEY,cursor INTEGER NOT NULL DEFAULT 0,pending_request TEXT)");
   s.execute("CREATE TABLE IF NOT EXISTS cloud_links(scope TEXT NOT NULL,local_id TEXT NOT NULL,cloud_id TEXT NOT NULL,base_version INTEGER NOT NULL,base_hash TEXT NOT NULL,base_payload TEXT NOT NULL,deleted INTEGER NOT NULL DEFAULT 0,restore INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(scope,local_id),UNIQUE(scope,cloud_id))");
   s.execute("CREATE TABLE IF NOT EXISTS cloud_conflicts(scope TEXT NOT NULL,local_id TEXT NOT NULL,local_payload TEXT NOT NULL,remote_event TEXT NOT NULL,PRIMARY KEY(scope,local_id))");
   s.execute("CREATE TABLE IF NOT EXISTS cloud_comments(scope TEXT NOT NULL,id TEXT NOT NULL,cloud_book_id TEXT NOT NULL,body TEXT NOT NULL,author_name TEXT NOT NULL,author_email TEXT NOT NULL,origin TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(scope,id))");
   s.execute("CREATE TABLE IF NOT EXISTS cloud_pending_notes(scope TEXT NOT NULL,id TEXT PRIMARY KEY,local_book_id TEXT NOT NULL,body TEXT NOT NULL)");
  }
  Path folder=Path.of(System.getProperty("catalogo.cloud.config",Path.of(System.getProperty("user.home"),".local","share","catalogo_livros","cloud").toString()));Files.createDirectories(folder);
  config=folder.resolve(hash(lib.database.toAbsolutePath().normalize()+"|"+databaseId)+".json");
 }
 static String api(){return endpoint(System.getProperty("catalogo.cloud.api","https://catalogo-livros-api.onrender.com"));}
 static String frontend(){return endpoint(System.getProperty("catalogo.cloud.frontend","https://biblioteca.praesens.tech"));}
 static String endpoint(String raw){URI u=URI.create(raw);if(u.getHost()==null||u.getUserInfo()!=null||u.getQuery()!=null||u.getFragment()!=null||!(u.getScheme().equals("https")||u.getScheme().equals("http")&&Set.of("localhost","127.0.0.1","::1").contains(u.getHost())))throw new IllegalArgumentException("Use HTTPS para conectar a biblioteca.");return raw.replaceAll("/+$","");}
 static String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 static JsonNode canonical(JsonNode node){if(node.isObject()){var result=Biblioteca.JSON.createObjectNode();var names=new ArrayList<String>();node.fieldNames().forEachRemaining(names::add);Collections.sort(names);for(String name:names)result.set(name,canonical(node.get(name)));return result;}if(node.isArray()){var out=Biblioteca.JSON.createArrayNode();node.forEach(n->out.add(canonical(n)));return out;}return node;}
 static String fingerprint(ObjectNode book,String cover)throws Exception{var copy=book.deepCopy();copy.remove(List.of("id","version"));var meta=(ObjectNode)copy.path("metadata");for(String field:PRIVATE)meta.remove(field);meta.remove(List.of("_stored_cover","_cloud_missing","_cloud_remote_path"));if(copy.path("kind").asText().equals("digital"))meta.remove("location");return hash(canonical(copy).toString()+"|"+hash(cover));}
 String scope(ConnectionInfo info){return info.api()+"|"+info.deviceId()+"|"+info.catalogId()+"|"+databaseId;}
 ConnectionInfo connection()throws Exception{if(!Files.exists(config))return null;var n=Biblioteca.JSON.readTree(Files.readString(config));if(!n.path("database_id").asText().equals(databaseId))throw new IllegalStateException("A conexão pertence a outro banco local.");return new ConnectionInfo(endpoint(n.path("api").asText()),n.path("device_id").asText(),n.path("catalog_id").asText(),n.path("email").asText(),n.path("token").asText(),databaseId);}
 void privateWrite(Path file,String text)throws Exception{Path tmp=Files.createTempFile(file.getParent(),"cloud-",".tmp");try{HtmlCatalog.restrictPermissions(tmp);Files.writeString(tmp,text);try{Files.move(tmp,file,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){Files.move(tmp,file,StandardCopyOption.REPLACE_EXISTING);}}finally{Files.deleteIfExists(tmp);}}
 String deviceId()throws Exception{Path file=Path.of(config+".device");if(Files.exists(file))return Files.readString(file).strip();String id=UUID.randomUUID().toString();privateWrite(file,id);return id;}
 JsonNode request(String api,String path,String token,Object body)throws Exception{
  var builder=HttpRequest.newBuilder(URI.create(endpoint(api)+path)).timeout(Duration.ofSeconds(45)).header("Accept","application/json");if(token!=null)builder.header("Authorization","Bearer "+token);
  if(body==null)builder.GET();else builder.header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(Biblioteca.JSON.writeValueAsString(body)));
  var response=http.send(builder.build(),HttpResponse.BodyHandlers.ofInputStream());byte[] data;try(var in=response.body()){data=in.readNBytes(8_000_001);}if(data.length>8_000_000)throw new IllegalStateException("Resposta de sincronização grande demais.");var result=Biblioteca.JSON.readTree(data);
  if(response.statusCode()==429)throw new IllegalStateException("Muitas requisições. Aguarde um minuto e tente sincronizar novamente; o lote foi preservado.");
  if(response.statusCode()>=400)throw new IllegalStateException(result.path("error").asText("Não foi possível conectar ao serviço (HTTP "+response.statusCode()+")."));return result;
 }
 Pairing startPair()throws Exception{byte[] random=new byte[32];new SecureRandom().nextBytes(random);String verifier=Base64.getUrlEncoder().withoutPadding().encodeToString(random),device=deviceId();var response=request(api(),"/device/pair",null,Map.of("device_id",device,"device_name","Catálogo desktop · "+System.getProperty("os.name"),"challenge",hash(verifier)));URI url=URI.create(response.path("verification_url").asText());URI expected=URI.create(frontend());if(!Objects.equals(url.getScheme(),expected.getScheme())||!Objects.equals(url.getAuthority(),expected.getAuthority()))throw new IllegalStateException("Endereço de autorização inesperado.");return new Pairing(response.path("id").asText(),response.path("user_code").asText(),url,verifier,device);}
 ConnectionInfo poll(Pairing pair)throws Exception{var response=request(api(),"/device/pair/"+pair.id()+"/token",null,Map.of("verifier",pair.verifier()));if(response.path("status").asText().equals("pending"))return null;if(!response.path("device_id").asText().equals(pair.deviceId())||!response.path("token").asText().equals("catd_"+pair.verifier()))throw new IllegalStateException("Resposta de associação inválida.");UUID.fromString(response.path("catalog_id").asText());var data=Biblioteca.JSON.createObjectNode();data.put("api",api());data.put("database_id",databaseId);for(String field:List.of("device_id","catalog_id","email","token"))data.put(field,response.path(field).asText());privateWrite(config,data.toString());return connection();}
 void disconnect(boolean newAccount)throws Exception{var info=connection();if(info!=null){var response=http.send(HttpRequest.newBuilder(URI.create(info.api()+"/api/devices/"+info.deviceId())).timeout(Duration.ofSeconds(20)).header("Authorization","Bearer "+info.token()).DELETE().build(),HttpResponse.BodyHandlers.discarding());if(response.statusCode()!=200&&response.statusCode()!=401)throw new IllegalStateException("Não foi possível revogar o dispositivo. Use Dispositivos conectados na web.");}Files.deleteIfExists(config);if(newAccount)privateWrite(Path.of(config+".device"),UUID.randomUUID().toString());}
 List<Local> snapshots(java.sql.Connection c,String id)throws Exception{var out=new ArrayList<Local>();String sql="SELECT b.*,m.favorite,m.reading,m.location,m.notes,p.cover_png,p.summary FROM books b LEFT JOIN marks m ON m.book_id=b.id LEFT JOIN book_previews p ON p.book_id=b.id WHERE "+(id==null?"b.active=1":"b.id=?")+" ORDER BY b.id";try(var q=c.prepareStatement(sql)){if(id!=null)q.setString(1,id);try(var r=q.executeQuery()){while(r.next()){
   var metadata=(ObjectNode)Biblioteca.JSON.readTree(r.getString("metadata_json"));boolean physical=LibraryCategories.physical(r.getString("section"));String path=r.getString("path");if(metadata.path("_cloud_missing").asBoolean()&&!Files.isRegularFile(lib.root.resolve(path)))path=metadata.path("_cloud_remote_path").asText(path);
   metadata=metadata.deepCopy();for(String key:PRIVATE)metadata.remove(key);metadata.remove(List.of("_stored_cover","_cloud_missing","_cloud_remote_path"));String notes=Objects.toString(r.getString("notes"),"");metadata.put("notes",notes);if(!notes.isBlank())metadata.put("notes_source","desktop");if(physical)metadata.put("location",Objects.toString(r.getString("location"),""));else metadata.remove("location");
   String url=metadata.path("_cloud_cover_url").asText();if(url.isBlank())for(var candidate:metadata.path("cover_urls")){if(candidate.asText().startsWith("https://")){url=candidate.asText();break;}}metadata.remove("_cloud_cover_url");
   var book=Biblioteca.JSON.createObjectNode();book.put("id","");book.put("title",Objects.toString(r.getString("title"),r.getString("filename")));book.put("kind",physical?"physical":"digital");book.put("format",r.getString("format"));book.put("path",path);book.put("filename",r.getString("filename"));book.put("category",r.getString("section"));book.set("metadata",metadata);book.put("summary",Objects.toString(r.getString("summary"),""));book.put("cover_url",url);book.put("favorite",r.getInt("favorite")==1);book.put("reading",r.getInt("reading")==1);book.put("version",0);
   byte[] cover=r.getBytes("cover_png");String encoded="";if(cover!=null&&cover.length<=524288){var image=javax.imageio.ImageIO.read(new java.io.ByteArrayInputStream(cover));if(image!=null&&image.getWidth()<=2000&&image.getHeight()<=2000){var png=new java.io.ByteArrayOutputStream();javax.imageio.ImageIO.write(image,"png",png);if(png.size()<=524288)encoded=Base64.getEncoder().encodeToString(png.toByteArray());}}
   out.add(new Local(r.getString("id"),r.getInt("active")==1,book,encoded));
  }}}return out;}
 Map<String,Link> links(java.sql.Connection c,String scope)throws Exception{var out=new LinkedHashMap<String,Link>();try(var q=c.prepareStatement("SELECT * FROM cloud_links WHERE scope=?")){q.setString(1,scope);try(var r=q.executeQuery()){while(r.next()){var link=new Link(r.getString("local_id"),r.getString("cloud_id"),r.getLong("base_version"),r.getString("base_hash"),r.getString("base_payload"),r.getInt("deleted")==1,r.getInt("restore")==1);out.put(link.localId(),link);}}}return out;}
 void putLink(java.sql.Connection c,String scope,String local,String cloud,long version,String hash,String base,boolean deleted,boolean restore)throws Exception{try(var q=c.prepareStatement("INSERT INTO cloud_links(scope,local_id,cloud_id,base_version,base_hash,base_payload,deleted,restore)VALUES(?,?,?,?,?,?,?,?)ON CONFLICT(scope,local_id)DO UPDATE SET cloud_id=excluded.cloud_id,base_version=excluded.base_version,base_hash=excluded.base_hash,base_payload=excluded.base_payload,deleted=excluded.deleted,restore=excluded.restore")){int i=1;for(Object value:List.of(scope,local,cloud,version,hash,base,deleted?1:0,restore?1:0))q.setObject(i++,value);q.executeUpdate();}}
 ObjectNode change(Local local,Link link)throws Exception{var item=Biblioteca.JSON.createObjectNode();item.put("local_id",local.id());item.put("base_version",link==null?0:link.version());item.put("deleted",false);item.put("restore",link!=null&&link.restore());var book=local.book().deepCopy();if(link!=null)book.put("id",link.cloudId());item.set("book",book);item.put("cover_png",local.cover());return item;}
 List<ObjectNode> changes(ConnectionInfo info,boolean confirmDeletes)throws Exception{String scope=scope(info);try(var c=lib.connect()){
  var links=links(c,scope);var all=snapshots(c,null);var active=new HashSet<String>();var conflicts=new HashSet<String>();try(var q=c.prepareStatement("SELECT local_id FROM cloud_conflicts WHERE scope=?")){q.setString(1,scope);try(var r=q.executeQuery()){while(r.next())conflicts.add(r.getString(1));}}
  var out=new ArrayList<ObjectNode>();for(var local:all){active.add(local.id());if(conflicts.contains(local.id()))continue;var link=links.get(local.id());if(link!=null&&link.deleted()&&!link.restore())continue;var notes=Biblioteca.JSON.createArrayNode();try(var q=c.prepareStatement("SELECT id,body FROM cloud_pending_notes WHERE scope=? AND local_book_id=?")){q.setString(1,scope);q.setString(2,local.id());try(var r=q.executeQuery()){while(r.next())notes.add(Biblioteca.JSON.valueToTree(Map.of("local_id",r.getString(1),"body",r.getString(2))));}}
   if(link==null||!fingerprint(local.book(),local.cover()).equals(link.hash())||!notes.isEmpty()||link.restore()){var item=change(local,link);item.set("annotations",notes);out.add(item);}
  }
  if(confirmDeletes)for(var link:links.values())if(!active.contains(link.localId())&&!link.deleted()&&!conflicts.contains(link.localId())&&Biblioteca.JSON.readTree(link.base()).path("kind").asText().equals("physical")){var item=Biblioteca.JSON.createObjectNode();item.put("local_id",link.localId());item.put("base_version",link.version());item.put("deleted",true);item.set("book",Biblioteca.JSON.readTree(link.base()));out.add(item);}
  return out;
 }}
 ObjectNode batch(ConnectionInfo info,List<ObjectNode> changes,boolean confirmDeletes,boolean pull)throws Exception{var body=Biblioteca.JSON.createObjectNode();body.put("request_id",UUID.randomUUID().toString());long cursor=0;try(var c=lib.connect();var q=c.prepareStatement("SELECT cursor FROM cloud_state WHERE scope=?")){q.setString(1,scope(info));try(var r=q.executeQuery()){if(r.next())cursor=r.getLong(1);}}body.put("cursor",cursor);body.put("confirm_deletions",confirmDeletes);body.put("pull",pull);body.set("changes",Biblioteca.JSON.valueToTree(changes));return body;}
 void pending(ConnectionInfo info,String json)throws Exception{try(var c=lib.connect();var q=c.prepareStatement("INSERT INTO cloud_state(scope,pending_request)VALUES(?,?)ON CONFLICT(scope)DO UPDATE SET pending_request=excluded.pending_request")){q.setString(1,scope(info));q.setString(2,json);q.executeUpdate();}}
 String pending(ConnectionInfo info)throws Exception{try(var c=lib.connect();var q=c.prepareStatement("SELECT pending_request FROM cloud_state WHERE scope=?")){q.setString(1,scope(info));try(var r=q.executeQuery()){return r.next()?r.getString(1):null;}}}
 void conflict(java.sql.Connection c,String scope,String local,JsonNode remote)throws Exception{var current=snapshots(c,local);var saved=Biblioteca.JSON.createObjectNode();if(!current.isEmpty()){saved.set("book",current.get(0).book());saved.put("cover_png",current.get(0).cover());saved.put("deleted",!current.get(0).active());}else{saved.put("deleted",true);var link=links(c,scope).get(local);if(link!=null)saved.set("book",Biblioteca.JSON.readTree(link.base()));}
  try(var q=c.prepareStatement("INSERT INTO cloud_conflicts(scope,local_id,local_payload,remote_event)VALUES(?,?,?,?)ON CONFLICT(scope,local_id)DO UPDATE SET remote_event=excluded.remote_event")){q.setString(1,scope);q.setString(2,local);q.setString(3,saved.toString());q.setString(4,remote.toString());q.executeUpdate();}
 }
 static String category(JsonNode book){String path=book.path("category").asText();boolean physical=book.path("kind").asText().equals("physical");if(path.isBlank())path=(physical?LibraryCategories.PHYSICAL:LibraryCategories.DIGITAL)+"/a_classificar";else if(physical&&!LibraryCategories.physical(path))path=LibraryCategories.PHYSICAL+"/"+path;else if(!physical)path=LibraryCategories.digital(path);if(path.length()>1000||path.startsWith("/")||path.contains("\\"))throw new IllegalArgumentException("Categoria remota inválida.");for(String part:path.split("/",-1))if(part.isBlank()||part.equals(".")||part.equals(".."))throw new IllegalArgumentException("Categoria remota inválida.");return path;}
 void applyBook(java.sql.Connection c,ConnectionInfo info,String localId,ObjectNode book,String cover,boolean deleted)throws Exception{
  var previous=snapshots(c,localId);boolean exists=!previous.isEmpty();String path;
  if(exists){try(var q=c.prepareStatement("SELECT path FROM books WHERE id=?")){q.setString(1,localId);try(var r=q.executeQuery()){r.next();path=r.getString(1);}}}else path="cloud/"+hash(info.api()+"|"+info.catalogId()+"|"+book.path("id").asText());
  if(deleted){if(exists){try(var q=c.prepareStatement("UPDATE books SET active=0,updated=? WHERE id=?")){q.setLong(1,System.currentTimeMillis());q.setString(2,localId);q.executeUpdate();}if(book.path("kind").asText().equals("physical")){try(var q=c.prepareStatement("DELETE FROM physical_books WHERE book_id=?")){q.setString(1,localId);q.executeUpdate();}}else{try(var q=c.prepareStatement("INSERT OR IGNORE INTO excluded_documents(path)VALUES(?)")){q.setString(1,path);q.executeUpdate();}}}return;}
  String category=category(book);LibraryCategories.add(c,category);var meta=(ObjectNode)book.path("metadata").deepCopy();for(String key:PRIVATE)meta.remove(key);meta.remove("_stored_cover");boolean physical=book.path("kind").asText().equals("physical");if(!physical&&(!exists||!Files.isRegularFile(lib.root.resolve(path)))){meta.put("_cloud_missing",true);meta.put("_cloud_remote_path",book.path("path").asText());}else{meta.remove(List.of("_cloud_missing","_cloud_remote_path"));}
  String coverURL=book.path("cover_url").asText();meta.put("_cloud_cover_url",coverURL);if(coverURL.startsWith("https://")){var urls=Biblioteca.JSON.createArrayNode();urls.add(coverURL);for(var old:meta.path("cover_urls"))if(!old.asText().equals(coverURL))urls.add(old);meta.set("cover_urls",urls);}
  long now=System.currentTimeMillis();if(exists){try(var q=c.prepareStatement("UPDATE books SET title=?,metadata_json=?,section=?,topic=?,format=?,filename=?,active=1,title_source='manual',updated=? WHERE id=?")){int i=1;for(Object value:List.of(book.path("title").asText(),meta.toString(),category,category.split("/")[0],book.path("format").asText(),book.path("filename").asText(),now,localId))q.setObject(i++,value);q.executeUpdate();}}
  else{try(var q=c.prepareStatement("INSERT INTO books(id,path,title,filename,topic,section,format,size,mtime_ns,metadata_json,title_source,active,updated)VALUES(?,?,?,?,?,?,?,0,0,?,'manual',1,?)")){int i=1;for(Object value:List.of(localId,path,book.path("title").asText(),book.path("filename").asText(),category.split("/")[0],category,book.path("format").asText(),meta.toString(),now))q.setObject(i++,value);q.executeUpdate();}}
  if(physical){String isbn=meta.path("isbn").asText();if(!isbn.isBlank())isbn=PhysicalBooks.isbn(isbn);String barcode=meta.path("barcode").asText();try(var q=c.prepareStatement("INSERT INTO physical_books(book_id,isbn,barcode)VALUES(?,NULLIF(?,''),NULLIF(?,''))ON CONFLICT(book_id)DO UPDATE SET isbn=excluded.isbn,barcode=excluded.barcode")){q.setString(1,localId);q.setString(2,isbn);q.setString(3,barcode);q.executeUpdate();}}
  try(var q=c.prepareStatement("INSERT INTO marks(book_id,favorite,reading,page,location,notes,updated)VALUES(?,?,?,1,?,?,?)ON CONFLICT(book_id)DO UPDATE SET favorite=excluded.favorite,reading=excluded.reading,notes=excluded.notes,location=CASE WHEN ? THEN excluded.location ELSE marks.location END,updated=excluded.updated")){q.setString(1,localId);q.setInt(2,book.path("favorite").asBoolean()?1:0);q.setInt(3,book.path("reading").asBoolean()?1:0);q.setString(4,physical?meta.path("location").asText():"");q.setString(5,meta.path("notes").asText());q.setLong(6,now);q.setBoolean(7,physical);q.executeUpdate();}
  byte[] image=cover.isBlank()?null:Base64.getDecoder().decode(cover);if(image!=null&&(image.length>524288||javax.imageio.ImageIO.read(new java.io.ByteArrayInputStream(image))==null))throw new IllegalArgumentException("Capa remota inválida.");
  try(var q=c.prepareStatement("INSERT INTO book_previews(book_id,cover_png,summary)VALUES(?,?,?)ON CONFLICT(book_id)DO UPDATE SET cover_png=COALESCE(excluded.cover_png,book_previews.cover_png),summary=excluded.summary")){q.setString(1,localId);q.setBytes(2,image);q.setString(3,book.path("summary").asText());q.executeUpdate();}
  if(image==null&&!coverURL.isBlank())CoverQueue.enqueue(c,localId);
 }
 String matchingPhysical(java.sql.Connection c,ObjectNode book)throws Exception{if(!book.path("kind").asText().equals("physical"))return null;String isbn=book.path("metadata").path("isbn").asText();if(isbn.isBlank())return null;try{isbn=PhysicalBooks.isbn(isbn);}catch(Exception e){return null;}try(var q=c.prepareStatement("SELECT book_id,isbn FROM physical_books WHERE isbn IS NOT NULL");var r=q.executeQuery()){while(r.next())try{if(PhysicalBooks.isbn(r.getString(2)).equals(isbn))return r.getString(1);}catch(IllegalArgumentException ignored){}}return null;}
 int apply(ConnectionInfo info,ObjectNode sent,JsonNode response)throws Exception{String scope=scope(info);int downloaded=0;lib.relations();try(var c=lib.connect()){c.setAutoCommit(false);try{
  var submitted=new HashMap<String,JsonNode>();for(var change:sent.path("changes"))submitted.put(change.path("local_id").asText(),change);
  for(var ack:response.path("accepted")){String local=ack.path("local_id").asText();var change=submitted.get(local);if(change==null)throw new IllegalStateException("Confirmação de lote inesperada.");var book=(ObjectNode)change.path("book");putLink(c,scope,local,ack.path("book_id").asText(),ack.path("version").asLong(),fingerprint(book,change.path("cover_png").asText()),book.toString(),ack.path("deleted").asBoolean(),false);for(var note:change.path("annotations"))try(var q=c.prepareStatement("DELETE FROM cloud_pending_notes WHERE scope=? AND id=?")){q.setString(1,scope);q.setString(2,note.path("local_id").asText());q.executeUpdate();}}
  for(var conflict:response.path("conflicts")){var event=Biblioteca.JSON.createObjectNode();event.set("book",conflict.path("remote"));event.put("deleted",conflict.path("deleted").asBoolean());event.put("cover_png",conflict.path("cover_png").asText());conflict(c,scope,conflict.path("local_id").asText(),event);}
  for(var event:response.path("events")){
   if(event.path("kind").asText().equals("comment")){var n=event.path("comment");try(var q=c.prepareStatement("INSERT INTO cloud_comments(scope,id,cloud_book_id,body,author_name,author_email,origin,created_at)VALUES(?,?,?,?,?,?,?,?)ON CONFLICT(scope,id)DO UPDATE SET body=excluded.body,author_name=excluded.author_name,author_email=excluded.author_email")){int i=1;for(Object value:List.of(scope,n.path("id").asText(),n.path("book_id").asText(),n.path("body").asText(),n.path("author_name").asText(),n.path("author_email").asText(),n.path("origin").asText(),n.path("created_at").asText()))q.setObject(i++,value);q.executeUpdate();}continue;}
   var book=(ObjectNode)event.path("book");String cloud=book.path("id").asText();var links=links(c,scope);Link link=links.values().stream().filter(l->l.cloudId().equals(cloud)).findFirst().orElse(null);
   String waiting=null;try(var q=c.prepareStatement("SELECT local_id,remote_event FROM cloud_conflicts WHERE scope=?")){q.setString(1,scope);try(var r=q.executeQuery()){while(r.next())if(Biblioteca.JSON.readTree(r.getString(2)).path("book").path("id").asText().equals(cloud)){waiting=r.getString(1);break;}}}
   if(waiting!=null){try(var q=c.prepareStatement("UPDATE cloud_conflicts SET remote_event=? WHERE scope=? AND local_id=?")){q.setString(1,event.toString());q.setString(2,scope);q.setString(3,waiting);q.executeUpdate();}continue;}
   if(link!=null&&book.path("version").asLong()<link.version())continue;
   String local=link==null?"cloud:"+hash(info.api()+"|"+info.catalogId()+"|"+cloud):link.localId();var current=snapshots(c,local);
   if(link==null&&!event.path("deleted").asBoolean()){String match=matchingPhysical(c,book);if(match!=null){conflict(c,scope,match,event);continue;}}
   if(link!=null&&book.path("version").asLong()==link.version()&&!current.isEmpty()&&!fingerprint(current.get(0).book(),current.get(0).cover()).equals(link.hash()))continue;
   if(link!=null&&!link.deleted()&&(current.isEmpty()||!fingerprint(current.get(0).book(),current.get(0).cover()).equals(link.hash()))){conflict(c,scope,local,event);continue;}
   applyBook(c,info,local,book,event.path("cover_png").asText(),event.path("deleted").asBoolean());var after=snapshots(c,local);String digest=after.isEmpty()?"":fingerprint(after.get(0).book(),after.get(0).cover());String base=after.isEmpty()?book.toString():after.get(0).book().toString();putLink(c,scope,local,cloud,book.path("version").asLong(),digest,base,event.path("deleted").asBoolean(),false);downloaded++;
  }
  if(sent.path("pull").asBoolean(true)){
  var remotePaths=new HashSet<String>();for(var path:response.path("categories"))remotePaths.add(path.asText());JsonNode previousStructure=Biblioteca.JSON.createObjectNode();try(var q=c.prepareStatement("SELECT snapshot FROM cloud_structure WHERE scope=?")){q.setString(1,scope);try(var r=q.executeQuery()){if(r.next())previousStructure=Biblioteca.JSON.readTree(r.getString(1));}}var removedPaths=new ArrayList<String>();for(var path:previousStructure.path("categories"))if(!remotePaths.contains(path.asText()))removedPaths.add(path.asText());removedPaths.sort(Comparator.comparingInt(String::length).reversed());for(String path:removedPaths)if(!Set.of(LibraryCategories.PHYSICAL,LibraryCategories.DIGITAL).contains(path))try(var q=c.prepareStatement("DELETE FROM categories WHERE path=? AND NOT EXISTS(SELECT 1 FROM books WHERE active=1 AND (section=? OR substr(section,1,length(?)+1)=?||'/')) AND NOT EXISTS(SELECT 1 FROM categories WHERE parent=?)")){for(int i=1;i<=5;i++)q.setString(i,path);q.executeUpdate();}
  for(var path:response.path("categories")){String value=path.asText();var descriptor=Biblioteca.JSON.createObjectNode();descriptor.put("kind",LibraryCategories.physical(value)?"physical":"digital");descriptor.put("category",value);LibraryCategories.add(c,category(descriptor));}
  var links=links(c,scope);var byCloud=new HashMap<String,String>();links.values().forEach(l->byCloud.put(l.cloudId(),l.localId()));try(var q=c.prepareStatement("DELETE FROM book_relations WHERE book_id IN(SELECT local_id FROM cloud_links WHERE scope=?) AND related_book_id IN(SELECT local_id FROM cloud_links WHERE scope=?)")){q.setString(1,scope);q.setString(2,scope);q.executeUpdate();}
  for(var rel:response.path("relations")){String a=byCloud.get(rel.path("book_id").asText()),b=byCloud.get(rel.path("related_book_id").asText()),kind=rel.path("kind").asText();if(a==null||b==null||a.equals(b)||!Set.of("same_work","sample_of").contains(kind))continue;try(var q=c.prepareStatement("INSERT OR IGNORE INTO book_relations(book_id,related_book_id,kind,source)VALUES(?,?,?,'cloud')")){q.setString(1,a);q.setString(2,b);q.setString(3,kind);q.executeUpdate();}}
  }
  try(var q=c.prepareStatement("UPDATE cloud_state SET cursor=?,pending_request=NULL WHERE scope=?")){q.setLong(1,response.path("cursor").asLong());q.setString(2,scope);q.executeUpdate();}c.commit();
 }catch(Exception e){c.rollback();throw e;}}lib.refreshSearchIndex();return downloaded;}
 Result sync(boolean confirmDeletes,Consumer<String> progress)throws Exception{
  var info=connection();if(info==null)throw new IllegalStateException("Conecte uma conta antes de sincronizar.");int uploaded=0,downloaded=0;
  String retry=pending(info);if(retry!=null&&!retry.isBlank()){progress.accept("Retomando o último lote…");var body=(ObjectNode)Biblioteca.JSON.readTree(retry);var result=request(info.api(),"/api/catalogs/"+info.catalogId()+"/sync",info.token(),body);downloaded+=apply(info,body,result);uploaded+=result.path("accepted").size();}
  var changes=changes(info,confirmDeletes);var chunk=new ArrayList<ObjectNode>();int size=0;for(var change:changes){if(Thread.currentThread().isInterrupted())throw new InterruptedException();int length=change.toString().getBytes(StandardCharsets.UTF_8).length;if(length>1400000)throw new IllegalStateException("Um cadastro excede o tamanho permitido para sincronização. Revise seus metadados e capa.");if(!chunk.isEmpty()&&(size+length>1400000||chunk.size()>=50)){var body=batch(info,chunk,confirmDeletes,false);pending(info,body.toString());progress.accept("Enviando "+chunk.size()+" cadastros…");var response=request(info.api(),"/api/catalogs/"+info.catalogId()+"/sync",info.token(),body);downloaded+=apply(info,body,response);uploaded+=response.path("accepted").size();chunk.clear();size=0;}chunk.add(change);size+=length;}
  if(!chunk.isEmpty()){var body=batch(info,chunk,confirmDeletes,false);pending(info,body.toString());progress.accept("Enviando "+chunk.size()+" cadastros…");var response=request(info.api(),"/api/catalogs/"+info.catalogId()+"/sync",info.token(),body);downloaded+=apply(info,body,response);uploaded+=response.path("accepted").size();}
  pushStructure(info);
  boolean more;do{if(Thread.currentThread().isInterrupted())throw new InterruptedException();progress.accept("Recebendo alterações e anotações…");var body=batch(info,List.of(),false,true);pending(info,body.toString());var response=request(info.api(),"/api/catalogs/"+info.catalogId()+"/sync",info.token(),body);downloaded+=apply(info,body,response);more=response.path("has_more").asBoolean();}while(more);
  saveStructure(info);return new Result(uploaded,downloaded,conflicts().size());
 }
 ObjectNode structure()throws Exception{var out=Biblioteca.JSON.createObjectNode();out.set("categories",Biblioteca.JSON.valueToTree(lib.categories()));var rels=Biblioteca.JSON.createArrayNode();for(var rel:lib.relations())rels.add(Biblioteca.JSON.valueToTree(Map.of("local_id",rel.book(),"related_local_id",rel.related(),"kind",rel.kind())));out.set("relations",rels);return out;}
 Set<String> items(JsonNode array){var out=new LinkedHashSet<String>();for(var n:array)out.add(canonical(n).toString());return out;}
 void saveStructure(ConnectionInfo info)throws Exception{try(var c=lib.connect();var q=c.prepareStatement("INSERT INTO cloud_structure(scope,snapshot)VALUES(?,?)ON CONFLICT(scope)DO UPDATE SET snapshot=excluded.snapshot")){q.setString(1,scope(info));q.setString(2,structure().toString());q.executeUpdate();}}
 void pushStructure(ConnectionInfo info)throws Exception{JsonNode old=Biblioteca.JSON.createObjectNode();try(var c=lib.connect();var q=c.prepareStatement("SELECT snapshot FROM cloud_structure WHERE scope=?")){q.setString(1,scope(info));try(var r=q.executeQuery()){if(r.next())old=Biblioteca.JSON.readTree(r.getString(1));}}var current=structure();
  for(String field:List.of("categories","relations")){var previous=items(old.path(field));var next=items(current.path(field));var changes=new ArrayList<JsonNode>();for(String value:next)if(!previous.contains(value))changes.add(Biblioteca.JSON.readTree(value));if(field.equals("relations"))for(String value:previous)if(!next.contains(value)){var removed=(ObjectNode)Biblioteca.JSON.readTree(value);removed.put("deleted",true);changes.add(removed);}
   if(field.equals("categories")){var removed=Biblioteca.JSON.createArrayNode();previous.stream().filter(v->!next.contains(v)).sorted(Comparator.comparingInt(String::length).reversed()).forEach(v->{try{removed.add(Biblioteca.JSON.readTree(v));}catch(Exception e){throw new IllegalStateException(e);}});if(!removed.isEmpty()){var body=batch(info,List.of(),false,false);body.set("category_deletions",removed);pending(info,body.toString());apply(info,body,request(info.api(),"/api/catalogs/"+info.catalogId()+"/sync",info.token(),body));}}
   for(int i=0;i<changes.size();i+=100){var body=batch(info,List.of(),false,false);body.set(field,Biblioteca.JSON.valueToTree(changes.subList(i,Math.min(changes.size(),i+100))));pending(info,body.toString());apply(info,body,request(info.api(),"/api/catalogs/"+info.catalogId()+"/sync",info.token(),body));}
  }
 }
 List<ObjectNode> conflicts()throws Exception{var info=connection();if(info==null)return List.of();var out=new ArrayList<ObjectNode>();try(var c=lib.connect();var q=c.prepareStatement("SELECT local_id,local_payload,remote_event FROM cloud_conflicts WHERE scope=?")){q.setString(1,scope(info));try(var r=q.executeQuery()){while(r.next()){var n=Biblioteca.JSON.createObjectNode();n.put("local_id",r.getString(1));n.set("local",Biblioteca.JSON.readTree(r.getString(2)));n.set("remote",Biblioteca.JSON.readTree(r.getString(3)));out.add(n);}}}return out;}
 void resolve(String localId,boolean keepLocal)throws Exception{var info=connection();if(info==null)throw new IllegalStateException("Conecte sua conta.");String scope=scope(info);try(var c=lib.connect()){c.setAutoCommit(false);try{JsonNode remote;try(var q=c.prepareStatement("SELECT remote_event FROM cloud_conflicts WHERE scope=? AND local_id=?")){q.setString(1,scope);q.setString(2,localId);try(var r=q.executeQuery()){if(!r.next())return;remote=Biblioteca.JSON.readTree(r.getString(1));}}
  var book=(ObjectNode)remote.path("book");if(keepLocal){var current=snapshots(c,localId);putLink(c,scope,localId,book.path("id").asText(),book.path("version").asLong(),"",book.toString(),current.isEmpty()&&remote.path("deleted").asBoolean(),!current.isEmpty()&&remote.path("deleted").asBoolean());}
  else{applyBook(c,info,localId,book,remote.path("cover_png").asText(),remote.path("deleted").asBoolean());var after=snapshots(c,localId);String digest=after.isEmpty()?"":fingerprint(after.get(0).book(),after.get(0).cover());putLink(c,scope,localId,book.path("id").asText(),book.path("version").asLong(),digest,after.isEmpty()?book.toString():after.get(0).book().toString(),remote.path("deleted").asBoolean(),false);}
  try(var q=c.prepareStatement("DELETE FROM cloud_conflicts WHERE scope=? AND local_id=?")){q.setString(1,scope);q.setString(2,localId);q.executeUpdate();}c.commit();}catch(Exception e){c.rollback();throw e;}}lib.refreshSearchIndex();}
 List<Map<String,String>> comments(String localId)throws Exception{var info=connection();if(info==null)return List.of();var out=new ArrayList<Map<String,String>>();try(var c=lib.connect();var q=c.prepareStatement("SELECT n.* FROM cloud_comments n JOIN cloud_links l ON l.cloud_id=n.cloud_book_id AND l.scope=n.scope WHERE n.scope=? AND l.local_id=? ORDER BY n.created_at,n.id")){q.setString(1,scope(info));q.setString(2,localId);try(var r=q.executeQuery()){while(r.next())out.add(Map.of("body",r.getString("body"),"author",r.getString("author_name"),"email",r.getString("author_email"),"origin",r.getString("origin"),"created",r.getString("created_at")));}}return out;}
 void addComment(String localId,String body)throws Exception{var info=connection();if(info==null)throw new IllegalStateException("Conecte sua conta.");if(body.isBlank()||body.getBytes(StandardCharsets.UTF_8).length>20000)throw new IllegalArgumentException("Escreva uma anotação com até 20.000 bytes.");try(var c=lib.connect();var q=c.prepareStatement("INSERT INTO cloud_pending_notes(scope,id,local_book_id,body)VALUES(?,?,?,?)")){q.setString(1,scope(info));q.setString(2,UUID.randomUUID().toString());q.setString(3,localId);q.setString(4,body);q.executeUpdate();}}
}
